package aarnav100.developer.biblescroll.data.bible

import androidx.room.ColumnInfo
import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey

/*
 * Tables of the bundled, read-only Bible database (assets/bible.db).
 *
 * The asset is generated by tools/build_bible_db.py, which takes its CREATE statements from
 * the Room schema export (app/schemas/...BibleDatabase/<version>.json). Any change here must
 * bump BibleDatabase.version, rebuild the app once to export the new schema, then rerun the
 * script — otherwise Room's schema validation will reject the asset at runtime.
 *
 * No foreign keys on purpose: the data never changes at runtime and the build script
 * validates integrity, so FK indices would only add size.
 */

@Entity(tableName = "translations")
data class TranslationEntity(
    @PrimaryKey
    @ColumnInfo(name = "id") val id: String, // e.g. "KJV", "WEB"
    @ColumnInfo(name = "name") val name: String,
    @ColumnInfo(name = "language_code") val languageCode: String,
    @ColumnInfo(name = "licence") val licence: String,
    @ColumnInfo(name = "sort_order") val sortOrder: Int,
)

@Entity(tableName = "books")
data class BookEntity(
    /** Canonical Protestant order, 1 (Genesis) .. 66 (Revelation). */
    @PrimaryKey
    @ColumnInfo(name = "id") val id: Int,
    /** USFM/Paratext book code, e.g. "GEN", "1CO". */
    @ColumnInfo(name = "code") val code: String,
    @ColumnInfo(name = "name") val name: String,
    /** "OT" or "NT". */
    @ColumnInfo(name = "testament") val testament: String,
    @ColumnInfo(name = "chapter_count") val chapterCount: Int,
)

/** Per translation, because verse counts differ (e.g. Romans 14 has 23 verses in KJV, 26 in WEB). */
@Entity(
    tableName = "chapters",
    primaryKeys = ["translation_id", "book_id", "chapter"],
)
data class ChapterEntity(
    @ColumnInfo(name = "translation_id") val translationId: String,
    @ColumnInfo(name = "book_id") val bookId: Int,
    @ColumnInfo(name = "chapter") val chapter: Int,
    /**
     * Number of verse rows in this chapter. Verses with no text in a translation are omitted
     * (e.g. WEB Acts 8:37, which is footnote-only), so numbers can have gaps.
     */
    @ColumnInfo(name = "verse_count") val verseCount: Int,
    /** Psalm title ("A Psalm of David…"), shown above verse 1; null elsewhere. */
    @ColumnInfo(name = "superscription") val superscription: String?,
)

@Entity(
    tableName = "verses",
    primaryKeys = ["translation_id", "book_id", "chapter", "verse"],
    indices = [
        // Feed paging: "next N verses after this one", across chapter/book boundaries.
        Index(value = ["translation_id", "ordinal"], unique = true),
        // Compare Versions: same reference across all translations.
        Index(value = ["book_id", "chapter", "verse"]),
    ],
)
data class VerseEntity(
    @ColumnInfo(name = "translation_id") val translationId: String,
    @ColumnInfo(name = "book_id") val bookId: Int,
    @ColumnInfo(name = "chapter") val chapter: Int,
    @ColumnInfo(name = "verse") val verse: Int,
    /** 1-based position of the verse within its translation, in canonical order. */
    @ColumnInfo(name = "ordinal") val ordinal: Int,
    /** Plain text: no markup, footnotes or Strong's numbers. */
    @ColumnInfo(name = "text") val text: String,
    /**
     * Words of Jesus as "start-end" UTF-16 offset pairs into [text] (end exclusive),
     * separated by ';' — e.g. "12-48;60-95". Null when the verse has none.
     */
    @ColumnInfo(name = "jesus_ranges") val jesusRanges: String?,
)
